WITH c AS (
  SELECT * FROM conversations WHERE id=$1::bigint FOR UPDATE
), d AS (
  SELECT c.context_json->'order_draft' AS draft,c.customer_id FROM c
), p AS (
  SELECT p.* FROM products p
  WHERE p.id=NULLIF((SELECT draft->>'product_id' FROM d),'')::bigint
    AND p.account_id=$3::bigint AND p.active=TRUE
), valid AS (
  SELECT draft,customer_id,(draft ? 'customer_name' AND draft ? 'phone' AND draft ? 'product_id' AND draft ? 'quantity' AND draft ? 'address' AND draft ? 'area_name' AND draft ? 'thana' AND draft ? 'district' AND draft ? 'payment_method' AND EXISTS(SELECT 1 FROM p)) AS ok FROM d
), ins_order AS (
  INSERT INTO orders(order_number,customer_id,business_id,account_id,status,customer_name,phone,address,area_name,thana,district,subtotal,delivery_charge,total,payment_method,note,confirmed_at)
  SELECT 'ORD-'||to_char(NOW(),'YYYYMMDD')||'-'||upper(substr(md5(random()::text),1,6)),v.customer_id,$2,$3::bigint,'CONFIRMED',v.draft->>'customer_name',v.draft->>'phone',v.draft->>'address',v.draft->>'area_name',v.draft->>'thana',v.draft->>'district',(GREATEST(1,(v.draft->>'quantity')::int)*p.price),$4::numeric,(GREATEST(1,(v.draft->>'quantity')::int)*p.price)+$4::numeric,v.draft->>'payment_method',v.draft->>'note',NOW()
  FROM valid v CROSS JOIN p WHERE v.ok RETURNING *
), ins_item AS (
  INSERT INTO order_items(order_id,product_id,sku,product_name,quantity,unit_price,total)
  SELECT o.id,p.id,p.external_product_id,p.name,GREATEST(1,(v.draft->>'quantity')::int),p.price,GREATEST(1,(v.draft->>'quantity')::int)*p.price FROM ins_order o CROSS JOIN p CROSS JOIN valid v RETURNING *
), upd AS (
  UPDATE conversations SET state=CASE WHEN EXISTS(SELECT 1 FROM ins_order) THEN 'ORDER_CONFIRMED' ELSE state END,context_json=CASE WHEN EXISTS(SELECT 1 FROM ins_order) THEN (context_json-'order_draft')||jsonb_build_object('last_order_id',(SELECT id FROM ins_order)) ELSE context_json END,followup_enabled=FALSE,next_followup_at=NULL,updated_at=NOW() WHERE id=$1::bigint RETURNING *
)
SELECT $5::jsonb AS base,EXISTS(SELECT 1 FROM ins_order) AS confirmed,(SELECT order_number FROM ins_order) AS order_number,(SELECT customer_name FROM ins_order) AS customer_name,(SELECT phone FROM ins_order) AS phone,(SELECT address FROM ins_order) AS address,(SELECT total FROM ins_order) AS total,(SELECT status FROM ins_order) AS order_status,(SELECT product_name FROM ins_item) AS product_name,(SELECT quantity FROM ins_item) AS quantity,(SELECT unit_price FROM ins_item) AS unit_price FROM upd;

